        require(address(this).balance >= putAmount);

        // Move the caller's unlock time into the past so that Collect can proceed.
        c.Put{value: putAmount}(0);
        (uint unlockTime1, uint balance1) = c.Acc(address(this));

        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }

