    function run(uint v1, uint v2, uint unlockTime, uint am) public payable {
        require(address(this).balance >= v1 + v2);

        // Record the initial ether balance of the test and c.
        uint beforeSelf = address(this).balance;
        uint beforeC = address(c).balance;

        // First deposit from the test contract.
        c.Put{value: v1}(unlockTime);

        // Second deposit from the test contract.
        c.Put{value: v2}(unlockTime);

        // Maker's balance after the two puts should equal v1 + v2.
        (uint ul, uint bal) = c.Acc(address(this));
        assert(bal == v1 + v2);

        // The unlock time must be at least the current block timestamp after Put.
        assert(ul >= block.timestamp);

        // If a Collect is possible (enough balance, enough ether, and the
        // unlock time has passed), it should succeed and move exactly `am`
        // Ether from c back to the test contract, reducing the recorded
        // balance by `am`.
        bool didCollect = false;
        if (bal >= 1 ether && bal >= am && block.timestamp > ul) {
            c.Collect(am);
            didCollect = true;
        }

        if (didCollect) {
            (uint ul2, uint bal2) = c.Acc(address(this));
            assert(bal2 == bal - am);
            assert(address(c).balance == beforeC + v1 + v2 - am);
            assert(address(this).balance == beforeSelf - v1 - v2 + am);
        } else {
            (uint ul3, uint bal3) = c.Acc(address(this));
            assert(bal3 == bal);
            assert(address(c).balance == beforeC + v1 + v2);
        }
    }
}
